import readline, rlcompleter, os, tempfile
print(readline.get_current_history_length(), readline.get_history_length())
for l in ("one", "two", "three"):
    readline.add_history(l)
print(readline.get_current_history_length(), readline.get_history_item(1), readline.get_history_item(3), readline.get_history_item(0), readline.get_history_item(4))
readline.replace_history_item(1, "TWO")
print(readline.get_history_item(2))
readline.remove_history_item(0)
print(readline.get_current_history_length(), readline.get_history_item(1))
for f in (lambda: readline.remove_history_item(5), lambda: readline.replace_history_item(9, "x"), lambda: readline.add_history(1)):
    try: f()
    except Exception as e: print(type(e).__name__)
p = os.path.join(tempfile.mkdtemp(), "h")
readline.write_history_file(p)
print([l for l in open(p).read().splitlines() if not l.startswith("_Hi")])
readline.clear_history()
print(readline.get_current_history_length())
readline.read_history_file(p)
print(readline.get_current_history_length(), readline.get_history_item(2))
readline.set_history_length(50)
print(readline.get_history_length())
readline.set_history_length(-1)
print(readline.get_completer() is None)
readline.parse_and_bind("tab: complete")
c = rlcompleter.Completer({"alpha": 1, "alphabet": 2, "beta": 3})
readline.set_completer(c.complete)
print(readline.get_completer() == c.complete)
print([c.complete("alp", i) for i in range(4)])
print([c.complete("be", i) for i in range(2)])
print(c.complete("os.pa", 0) is None or True)
c2 = rlcompleter.Completer()
print(sorted(set(c2.complete("pri", i) for i in range(5)) - {None}))
print(c2.complete("len(", 0))
print(readline.get_line_buffer() == "", readline.backend in ("readline", "editline"))
